// Brand marks for the relay. `Logo` is the mark rendered *inside* the relay canvas
// (x/y/size); `LogoHtml` is the same mark as plain DOM for the lifecycle rail and
// the side panel; UiPathMark / MicrosoftMark are the legend chips.
//
// UiPath and WhatsApp are raster marks inlined here (from the kit). Everything
// else is resolved by name in ./productLogos — the Microsoft artwork from the
// target-state page, plus monogram tiles for the Nigerian rails and the bank's
// own systems, which have no artwork in the product set. ProductLogo falls back
// to the UiPath mark for a name it does not know, so a new third-party product
// needs its own entry there.
import { ProductLogo } from './productLogos';

// WhatsApp's own mark (supplied artwork), outer white cleared.
const WHATSAPP_MARK = 'data:image/png;base64,';
const UIPATH_MARK = 'data:image/png;base64,';

// HTML chips for legends.
export function UiPathMark({ className = 'h-4 w-4' }: { className?: string }) {
  return <img src={UIPATH_MARK} className={`${className} block shrink-0`} role="img" aria-label="UiPath" alt="" style={{ objectFit: 'contain' }} />;
}
export function MicrosoftMark({ className = 'h-4 w-4' }: { className?: string }) {
  return (
    <svg viewBox="0 0 24 24" className={className} role="img" aria-label="Microsoft">
      <rect x="1" y="1" width="10" height="10" fill="#F25022" />
      <rect x="13" y="1" width="10" height="10" fill="#7FBA00" />
      <rect x="1" y="13" width="10" height="10" fill="#00A4EF" />
      <rect x="13" y="13" width="10" height="10" fill="#FFB900" />
    </svg>
  );
}

// The two national registers' own marks (supplied artwork, inlined so they
// resolve under the coded-app base path as well as on localhost).
const NIMC_MARK = 'data:image/png;base64,';
const NIBSS_MARK = 'data:image/png;base64,';

// Kafka's own symbol, cropped from the supplied wordmark (the card already says
// "Kafka"), with the white ground made transparent so it sits on tinted cards.
const KAFKA_MARK = 'data:image/png;base64,';

// Finacle's red mark, cropped from the supplied wordmark (the card already says
// "Finacle"), outer white cleared.
const FINACLE_MARK = 'data:image/png;base64,';

const RASTER: Record<string, string> = { uipath: UIPATH_MARK, whatsapp: WHATSAPP_MARK, NIMC: NIMC_MARK, NIBSS: NIBSS_MARK, Kafka: KAFKA_MARK, Finacle: FINACLE_MARK };

/** Marks drawn larger on their card: a detailed seal and a wide wordmark that
    read as specks at the standard 22px. Only the mark grows — into the margin
    left of the card's text, which does not move. */
export const LARGE_MARKS = new Set(['NIMC', 'NIBSS']);

// The `bank` logo key is the admin theme's square mark, not a fixed asset, so the
// caller passes it in as `bankMark` on every call. It used to be written into
// RASTER during render; a hot reload of this module wiped it and the bank's cards
// fell back to the UiPath mark until a full reload.
const srcFor = (name: string, bankMark?: string) => (name === 'bank' ? bankMark : RASTER[name]);

// The mark rendered inside the relay canvas.
export function Logo({ name, x, y, size = 18, bankMark }: { name: string; x: number; y: number; size?: number; bankMark?: string }) {
  const src = srcFor(name, bankMark);
  if (src) return <image href={src} x={x} y={y} width={size} height={size} preserveAspectRatio="xMidYMid meet" />;
  return (
    <foreignObject x={x} y={y} width={size} height={size} style={{ overflow: 'visible' }}>
      <ProductLogo name={name} cls="h-full w-full" />
    </foreignObject>
  );
}

// The same marks as HTML rather than positioned SVG — the lifecycle rail is a
// normal DOM list, so it cannot use the <image>/<foreignObject> form `Logo` emits.
export function LogoHtml({ name, className = 'h-4 w-4', bankMark }: { name: string; className?: string; bankMark?: string }) {
  if (name === 'uipath') return <UiPathMark className={className} />;
  const src = srcFor(name, bankMark);
  if (src) return <img src={src} className={`${className} block shrink-0`} role="img" aria-label={name} alt="" style={{ objectFit: 'contain' }} />;
  return <ProductLogo name={name} cls={className} />;
}
